function unpack(): CityData[] {
  const out: CityData[] = [];
  for (const block of PACKED.split('\n')) {
    const split = block.indexOf('^');
    const region = block.slice(0, split);
    let lat = 0;
    let lon = 0;
    for (const row of block.slice(split + 1).split('|')) {
      const f = row.split('~');
      lat += parseInt(f[1], 36);
      lon += parseInt(f[2], 36);
      const city: CityData = {
        name: f[0],
        country: 'Canada',
        region,
        lat: lat / 10000,
        lon: lon / 10000,
      };
      if (f[3]) city.population = parseInt(f[3], 36);
      out.push(city);
    }
  }
  return out;
}

export const CANADA_CITIES: CityData[] = unpack();
